function rgb_to_hsv(r, g, b) {
  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);
  const delta = max - min;

  let hue;
  if (delta === 0) {
    hue = 0;
  } else if (max === r) {
    hue = (60 * ((g - b) / delta)) % 360;
  } else if (max === g) {
    hue = (60 * ((b - r) / delta)) + 120;
  } else {
    hue = (60 * ((r - g) / delta)) + 240;
  }

  const saturation = (max === 0) ? 0 : delta / max;
  const value = max;

  return { hue, saturation, value };
}

function rgb_to_hsv(r, g, b){
  // Convert RGB to HSV
  let max = Math.max(r, g, b);
  let min = Math.min(r, g, b);
  let delta = max - min;

  let h;
  let s;
  let v = max;

  if (delta === 0) {
    h = 0;
    s = 0;
  } else {
    s = delta / v;

    let rc = (max - r) / delta;
    let gc = (max - g) / delta;
    let bc = (max - b) / delta;

    if (r === max) {
      h = (gc - bc) / delta;
    } else if (g === max) {
      h = 2 + (bc - rc) / delta;
    } else {
      h = 4 + (rc - gc) / delta;
    }

    h = h / 6;
    if (h < 0) {
      h += 1;
    }
  }

  return { h: h, s: s, v: v };
}

