function combinations_colors(l, n) {
  // Initialize an array to hold all the combinations
  const combinations = [];

  // Create a recursive function to generate combinations
  function generateCombinations(current = [], index = 0) {
    if (current.length === n) {
      combinations.push(current);
      return;
    }

    for (let i = index; i < l; i++) {
      // Include the current element in the combination
      generateCombinations([...current, l[i]], i);
    }
  }

  // Start the recursion with an empty array
  generateCombinations();

  return combinations;
}

