function find_combinations(test_list) {
  function combine(arr, n, result) {
    if (n === 0) {
      result.push([...arr]);
      return;
    }
    for (let i = 0; i < arr.length; i++) {
      let new_arr = arr.slice(i + 1);
      combine(new_arr, n - 1, [...result, arr[i]]);
    }
  }

  let combinations = [];
  for (let n = 1; n <= test_list.length; n++) {
    combine(test_list, n, combinations);
  }
  return combinations;
}

function find_combinations(test_list){
  let combinations = [];
  function backtrack(start, currentSum, currentCombination) {
    if (currentSum === test_list.length) {
      combinations.push([...currentCombination]);
      return;
    }
    for (let i = start; i < test_list.length; i++) {
      currentCombination.push(test_list[i]);
      backtrack(i + 1, currentSum + test_list[i], currentCombination);
      currentCombination.pop();
    }
  }
  backtrack(0, 0, []);
  return combinations;
}

