function bell_Number(n) {
  // Base case for the Bell number
  if (n === 0) return 1;

  // Initialize an array to store Bell numbers
  const bell = new Array(n + 1).fill(0);
  bell[0] = 1; // Base case: Bell number for n=0 is 1

  // Initialize the second element of the Bell array
  bell[1] = 1;

  // Calculate Bell numbers for n > 1
  for (let i = 2; i <= n; i++) {
    bell[i] = 0;
    for (let j = 0; j < i; j++) {
      bell[i] += bell[j] * bell[i - 1 - j];
    }
  }

  return bell[n];
}

