function find_sum(arr) {
  let sum = 0;
  let frequency = {};

  // Count the frequency of each element in the array
  for (let i = 0; i < arr.length; i++) {
    if (!frequency[arr[i]]) {
      frequency[arr[i]] = 1;
    } else {
      frequency[arr[i]]++;
    }
  }

  // Sum the elements that appear exactly once
  for (let key in frequency) {
    if (frequency[key] === 1) {
      sum += parseInt(key);
    }
  }

  return sum;
}

