  if (n === 1) return 1;

  let a = 0, b = 1;
  let count = 2;

  while (count < n) {
    let next = a + b;
    a = b;
    b = next;
    count++;
  }

  return b;
}

function sequence(n){
    if (n === 1 || n === 2) return 1;
    const sequence = [1, 1];
    for (let i = 2; i <= n; i++) {
        sequence[i] = sequence[sequence[i-1]] + sequence[i-sequence[i-1]];
    }
    return sequence[n];
}

