function rgb_to_hsv(r, g, b) {
  // Convert RGB to HSV
  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);
  const delta = max - min;

  let h;
  let s;
  let v = max;

  if (delta === 0) {
    h = 0;
    s = 0;
  } else {
    s = delta / v;

    const rc = (max - r) / delta;
    const gc = (max - g) / delta;
    const bc = (max - b) / delta;

    if (r === max) {
      h = (bc - gc) / delta;
    } else if (g === max) {
      h = 2 + (rc - bc) / delta;
    } else {
      h = 4 + (gc - rc) / delta;
    }

    h *= 60;
    if (h < 0) h += 360;
  }

  return { h, s, v };
