function rgb_to_hsv(r, g, b) {
    // Convert RGB to HSV
    let max = Math.max(r, g, b);
    let min = Math.min(r, g, b);
    let delta = max - min;

    let hue;
    if (delta === 0) {
        hue = 0;
    } else if (max === r) {
        hue = ((g - b) / delta) % 6;
    } else if (max === g) {
        hue = ((b - r) / delta) + 2;
    } else {
        hue = ((r - g) / delta) + 4;
    }

    hue = hue * 60;

    let saturation;
    if (max === 0) {
        saturation = 0;
    } else {
        saturation = (delta / max) * 100;
    }

    let value = max * 100;

    return { hue, saturation, value };
}

