function toggle_middle_bits(n) {
  // Shift the bits of n to the right by 1 to isolate the first bit
  let first_bit = n >> 1;

  // Shift the bits of n to the left by 1 to isolate the last bit
  let last_bit = n << 1;

  // XOR the first bit and the last bit to toggle the middle bits
  let toggled_bits = first_bit ^ last_bit;

  // Return the original number with the middle bits toggled
  return n ^ toggled_bits;
}

function toggle_middle_bits(n) {
  // Check if the number is less than 2, in which case there are no middle bits to toggle
  if (n < 2) {
    return n;
  }

  // Extract the middle bits by shifting the number to the right and then left by the number of bits to be toggled
  const middle_bits = n >> 1;
  middle_bits ^= (1 << (Math.floor(Math.log2(n)) - 1));

  // Shift the middle bits back to the original position
  return middle_bits << 1;
}

