function minPath(grid, k) {
    const N = grid.length;
    let minPath = [];
    let visited = new Set();

    const directions = [
        [0, 1], [1, 0], [-1, 0], [0, -1]
    ];

    function dfs(row, col, steps) {
        if (steps === k) {
            minPath = [...grid[row][col]];
            return;
        }

        for (const [dx, dy] of directions) {
            const newRow = row + dx;
            const newCol = col + dy;

            if (newRow >= 0 && newRow < N && newCol >= 0 && newCol < N && !visited.has(`${newRow}-${newCol}`)) {
                visited.add(`${newRow}-${newCol}`);
                dfs(newRow, newCol, steps + 1);
                visited.delete(`${newRow}-${newCol}`);
            }
        }
    }

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            visited.add(`${i}-${j}`);
            dfs(i, j, 1);
            visited.delete(`${i}-${j}`);
        }
    }

    return minPath;
}

function minPath(grid, k) {
  const N = grid.length;
  const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]];

  const visited = new Array(N).fill().map(() => new Array(N).fill(false));
  const minPathLength = Infinity;
  const pathValues = [];

  const dfs = (x, y, currentLength, currentPath) => {
    if (currentLength === k) {
      if (currentPath.length < minPathLength || (currentPath.length === minPathLength && currentPath.join(',') < pathValues.join(','))) {
        minPathLength = currentLength;
        pathValues = currentPath;
      }
      return;
    }

    visited[x][y] = true;
    for (const [dx, dy] of directions) {
      const nx = x + dx;
      const ny = y + dy;
      if (nx >= 0 && nx < N && ny >= 0 && ny < N && !visited[nx][ny]) {
        dfs(nx, ny, currentLength + 1, currentPath.concat(grid[nx][ny]));
      }
    }
    visited[x][y] = false;
  };

  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      dfs(i, j, 1, [grid[i][j]]);
    }
  }

  return pathValues;
}

