function move_one_ball(arr) {
    // Check if the array is empty
    if (arr.length === 0) {
        return true;
    }

    // Create a copy of the array to perform shift operations
    let arrCopy = [...arr];

    // Function to perform right shift on an array
    function shiftRight(arr) {
        let lastElement = arr[arr.length - 1];
        for (let i = arr.length - 2; i >= 0; i--) {
            arr[i + 1] = arr[i];
        }
        arr[0] = lastElement;
    }

    // Perform right shift operations until the array is sorted
    for (let i = 0; i < arr.length; i++) {
        shiftRight(arrCopy);
        if (arrCopy.join('') === arr.join('')) {
            return true;
        }
    }

    // If no shift is required, the array is already sorted
    return false;
}

