function maxAverageOfPath(cost) {
    const n = cost.length;
    const dp = new Array(n).fill(null).map(() => new Array(n).fill(0));

    // Fill the first row and first column with the cost of the cells
    for (let i = 0; i < n; i++) {
        dp[0][i] = cost[0][i];
        dp[i][0] = cost[i][0];
    }

    // Fill the rest of the dp array
    for (let i = 1; i < n; i++) {
        for (let j = 1; j < n; j++) {
            dp[i][j] = Math.max(cost[i][j] + dp[i-1][j], cost[i][j] + dp[i][j-1]);
        }
    }

    // Calculate the maximum average
    const totalCost = cost.reduce((sum, row) => sum + row.reduce((sum, cell) => sum + cell, 0), 0);
    const pathLength = n * n;
    const maxAverage = totalCost / pathLength;

    return maxAverage;
}

function maxAverageOfPath(cost) {
    const N = cost.length;
    const dp = new Array(N).fill().map(() => new Array(N).fill(0));

    // Fill the dp table
    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            if (i === 0 && j === 0) {
                dp[i][j] = cost[i][j];
            } else if (i === 0) {
                dp[i][j] = dp[i][j - 1] + cost[i][j];
            } else if (j === 0) {
                dp[i][j] = dp[i - 1][j] + cost[i][j];
            } else {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost[i][j];
            }
        }
    }

    // Calculate the maximum average path
    let maxAverage = dp[N - 1][N - 1];
    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            maxAverage = Math.max(maxAverage, dp[i][j] / (i + j + 1));
        }
    }

    return maxAverage;
}

