  function countSequences(currentLength, previousValue) {
    if (currentLength === n) {
      count++;
      return;
    }

    // Loop through possible values for the current element
    for (let value = Math.max(previousValue, 2 * previousValue); value <= m; value++) {
      countSequences(currentLength + 1, value);
    }
  }

  // Start the recursion with the first element being 1 (since it must be greater than or equal to 2)
  countSequences(1, 1);

  return count;
}

