  for (let i = 0; i < binaryStr.length; i++) {
    // If the character is '1', it means there is a '1' in the binary representation
    if (binaryStr[i] === '1') {
      // Check if the previous character is also '1'
      // If it is, then the number cannot be represented as sum of non-zero powers of 2
      if (i > 0 && binaryStr[i-1] === '1') {
        return false;
      }
    }
  }

