        if (sum === 0) {
            combinations.push(arr.slice());
            return;
        }
        if (sum < 0 || start >= arr.length) {
            return;
        }
        for (let i = start; i < arr.length; i++) {
            arr.splice(i, 1);
            combine(arr, sum - arr[i], i);
            arr.splice(i, 0, arr[i]);
