function find_combinations(test_list) {
  const sums = [];

  function backtrack(arr, target, sum, path) {
    if (sum === target) {
      sums.push([...path]);
      return;
    }
    if (sum > target || arr.length === 0) {
      return;
    }
    path.push(arr.shift());
    backtrack(arr, target, sum + arr[0], path);
    path.pop();
    backtrack(arr.slice(1), target, sum, path);
  }

  for (let i = 0; i < test_list.length; i++) {
    for (let j = i + 1; j < test_list.length; j++) {
      backtrack([...test_list[i], ...test_list[j]], test_list[i].length + test_list[j].length, test_list[i].length, []);
    }
  }

  return sums;
}

