function rgb_to_hsv(r, g, b) {
  // Normalize RGB values to the range [0, 1]
  r = r / 255;
  g = g / 255;
  b = b / 255;

  // Find the maximum and minimum values in the RGB array
  let max = Math.max(r, g, b);
  let min = Math.min(r, g, b);

  // Calculate the difference between the maximum and minimum values
  let delta = max - min;

  // Calculate the saturation
  let saturation = delta === 0 ? 0 : delta / max;

  // Calculate the hue
  let hue = 0;
  if (delta !== 0) {
    if (max === r) {
      hue = (g - b) / delta;
    } else if (max === g) {
      hue = (b - r) / delta + 2;
    } else {
      hue = (r - g) / delta + 4;
    }
    hue = hue / 6;
  }

  // Convert hue to degrees
  hue = hue * 360;

  // Calculate the value
  let value = max;

  return {
    h: hue,
    s: saturation,
    v: value
  };
}

