function encode(message) {
    const vowels = 'aeiouAEIOU';
    const replacementMap = {
        'a': 'c', 'e': 'g', 'i': 'k', 'o': 'q', 'u': 's',
        'A': 'C', 'E': 'G', 'I': 'K', 'O': 'Q', 'U': 'S'
    };

    let encodedMessage = '';

    for (let char of message) {
        if (vowels.includes(char)) {
            const replacement = replacementMap[char];
            encodedMessage += replacement;
        } else {
            encodedMessage += char === char.toUpperCase() ? char.toLowerCase() : char.toUpperCase();
        }
    }

    return encodedMessage;
}

function encode(message) {
  // Helper function to get the letter that appears 2 places ahead of a vowel
  const getNextLetter = (vowel) => {
    const alphabet = 'abcdefghijklmnopqrstuvwxyz';
    const index = alphabet.indexOf(vowel.toLowerCase());
    const nextIndex = (index + 2) % 26; // Ensures we wrap around the alphabet
    return alphabet[nextIndex].toUpperCase();
  };

  // Replace vowels with the letter 2 places ahead and swap cases
  return message
    .split('')
    .map((char) => {
      if ('aeiouAEIOU'.includes(char)) {
        return getNextLetter(char);
      } else {
        return char === char.toUpperCase() ? char.toLowerCase() : char.toUpperCase();
      }
    })
    .join('');
}

