function get_total_number_of_sequences(m, n) {
  if (n === 1) {
    return 1;
  }
  let total = 0;
  for (let i = Math.max(1, 2 * m - n + 1); i <= m; i++) {
    total += get_total_number_of_sequences(m, n - 1);
  }
  return total;
}

function get_total_number_of_sequences(m, n) {
    // Helper function to calculate the binomial coefficient
    function binomialCoefficient(n, k) {
        let result = 1;
        for (let i = 0; i < k; i++) {
            result *= (n - i);
            result /= (i + 1);
        }
        return result;
    }

    // Helper function to calculate the number of valid sequences
    function countValidSequences(m, n) {
        // Calculate the maximum possible value of the second element in the sequence
        let maxSecond = Math.min(m / 2, n - 1);
        let count = 0;

        // Iterate over all possible values of the second element
        for (let second = 1; second <= maxSecond; second++) {
            let remaining = n - 1;
            let countForSecond = binomialCoefficient(remaining, second - 1);
            count += countForSecond;
        }

        return count;
    }

    // Calculate the total number of valid sequences
    return countValidSequences(m, n);
}

