function find_combinations(test_list) {
  // Initialize an array to store all combinations
  const combinations = [];

  // Helper function to recursively generate combinations
  function generate_combinations(index, current_combination) {
    // If the current combination sum is equal to the target sum, add it to the combinations array
    if (current_combination.reduce((acc, num) => acc + num, 0) === test_list[0]) {
      combinations.push(current_combination.slice());
    }

    // Iterate over the remaining elements in the test list
    for (let i = index; i < test_list.length; i++) {
      // Add the current element to the current combination
      current_combination.push(test_list[i]);
      // Recursively generate combinations with the next element
      generate_combinations(i + 1, current_combination);
      // Backtrack by removing the last element from the current combination
      current_combination.pop();
    }
  }

  // Start the recursion from the first index with an empty current combination
  generate_combinations(0, []);

  return combinations;
}

