function minPath(grid, k){
    const rows = grid.length;
    const cols = grid[0].length;
    const visited = new Set();
    const path = [];

    const directions = [
        [0, 1], // right
        [1, 0], // down
        [-1, 0], // up
        [0, -1]  // left
    ];

    const dfs = (x, y, steps) => {
        if (steps === k) {
            path.push(grid[x][y]);
            return;
        }

        visited.add(`${x},${y}`);

        for (const [dx, dy] of directions) {
            const nx = x + dx;
            const ny = y + dy;

            if (nx >= 0 && nx < rows && ny >= 0 && ny < cols && !visited.has(`${nx},${ny}`)) {
                dfs(nx, ny, steps + 1);
            }
        }

        visited.delete(`${x},${y}`);
    };

    for (let i = 0; i < rows; i++) {
        for (let j = 0; j < cols; j++) {
            dfs(i, j, 1);
        }
    }

    path.sort((a, b) => a - b);

    return path.slice(0, k);
}

