function search(arr){
    let left = 0;
    let right = arr.length - 1;

    while (left < right) {
        let mid = Math.floor((left + right) / 2);

        // If the mid element is at the start or end, or the element at mid is different from its neighbors, it is the single element
        if (mid === 0 || arr[mid] !== arr[mid - 1] && arr[mid] !== arr[mid + 1]) {
            return arr[mid];
        }

        // If the mid element is greater than the next element, the single element must be in the left half
        if (arr[mid] > arr[mid + 1]) {
            right = mid;
        } else {
            // Otherwise, the single element must be in the right half
            left = mid + 1;
        }
    }

    // If no single element is found, the left pointer will be at the single element
    return arr[left];
}

