function rearrange_bigger(n) {
    const str = n.toString().split('');
    const len = str.length;

    // Find the first digit from the right that is smaller than the digit next to it
    let i = len - 2;
    while (i >= 0 && str[i] >= str[i + 1]) {
        i--;
    }

    if (i === -1) {
        return -1; // The number is the largest possible permutation
    }

    // Find the smallest digit to the right of i that is greater than str[i]
    let j = len - 1;
    while (j >= 0 && str[j] <= str[i]) {
        j--;
    }

    // Swap str[i] and str[j]
    [str[i], str[j]] = [str[j], str[i]];

    // Sort the digits to the right of i in ascending order
    str.splice(i + 1, len - i - 1).sort((a, b) => a - b);

    // Convert the sorted array back to a number
    return parseInt(str.join(''), 10);
}

function rearrange_bigger(n) {
  // Convert the number to a string
  let str = n.toString();
  // Get the length of the string
  let len = str.length;

  // Find the first position from the right where the digit is smaller than the digit to its right
  let index = len - 2;
  while (index >= 0 && str[index] >= str[index + 1]) {
    index--;
  }

  // If no such digit is found, the number is the largest possible permutation
  if (index === -1) {
    return -1;
  }

  // Find the smallest digit to the right of the found digit that is greater than it
  let swapIndex = len - 1;
  while (str[swapIndex] <= str[index]) {
    swapIndex--;
  }

  // Swap the found digit and the smallest digit
  [str[index], str[swapIndex]] = [str[swapIndex], str[index]];

  // Sort the digits to the right of the swapped digit in ascending order
  let rightPart = str.slice(index + 1).split('').sort((a, b) => a.localeCompare(b)).join('');

  // Combine the parts to form the next bigger number
  return parseInt(str.slice(0, index + 1) + rightPart);
}

