function rgb_to_hsv(r, g, b) {
    // Normalize RGB values to the range [0, 1]
    r /= 255;
    g /= 255;
    b /= 255;

    // Find the maximum and minimum values
    let max = Math.max(r, g, b);
    let min = Math.min(r, g, b);

    // Calculate the value (V)
    let v = max;

    // Calculate the saturation (S)
    let s = max === 0 ? 0 : (max - min) / max;

    // Calculate the hue (H)
    let h;
    if (max === min) {
        h = 0;
    } else if (r === max) {
        h = (g - b) / (max - min);
    } else if (g === max) {
        h = 2 + (b - r) / (max - min);
    } else {
        h = 4 + (r - g) / (max - min);
    }

    // Convert hue to degrees
    h = h * 60;

    // Ensure hue is within the range [0, 360]
    h = h % 360;

    return { h, s, v };
}

function rgb_to_hsv(r, g, b){
    r /= 255.0;
    g /= 255.0;
    b /= 255.0;
    const max = Math.max(r, g, b);
    const min = Math.min(r, g, b);
    const delta = max - min;
    let h;
    let s;
    let v = max;

    if (delta === 0) {
        h = s = 0;
    } else {
        s = delta / v;
        if (r === max) {
            h = (g - b) / delta;
        } else if (g === max) {
            h = 2 + (b - r) / delta;
        } else {
            h = 4 + (r - g) / delta;
        }
        h /= 6.0;
        if (h < 0) h += 1;
    }

    return { h, s, v };
}

