function rearrange_bigger(n) {
  const digits = Array.from(n.toString()).map(Number);
  let found = false;

  for (let i = digits.length - 2; i >= 0; i--) {
    if (digits[i] < digits[i + 1]) {
      let j = digits.length - 1;
      while (digits[j] <= digits[i]) {
        j--;
      }
      let temp = digits[i];
      digits[i] = digits[j];
      digits[j] = temp;

      let subArray = digits.slice(i + 1).sort((a, b) => a - b);
      let result = parseInt(digits.slice(0, i + 1).join('') + subArray.join(''));

      return result;
    }
  }

  return -1; // No bigger rearrangement possible
