function rgb_to_hsv(r, g, b) {
    let max = Math.max(r, g, b);
    let min = Math.min(r, g, b);
    let delta = max - min;

    let h;
    let s;
    let v = max;

    if (delta === 0) {
        h = 0;
        s = 0;
    } else {
        s = delta / v;

        let rc = (max - r) / delta;
        let gc = (max - g) / delta;
        let bc = (max - b) / delta;

        if (r === max) {
            h = (gc - bc) / delta;
        } else if (g === max) {
            h = 2 + (bc - rc) / delta;
        } else {
            h = 4 + (rc - gc) / delta;
        }

        h = h / 6;
        if (h < 0) h += 1;
    }

    return [h, s, v];
}

function rgb_to_hsv(r, g, b) {
  let max = Math.max(r, g, b);
  let min = Math.min(r, g, b);
  let delta = max - min;

  let hue;
  if (delta === 0) {
    hue = 0;
  } else if (max === r) {
    hue = (60 * ((g - b) / delta)) % 360;
  } else if (max === g) {
    hue = (60 * ((b - r) / delta)) + 120;
  } else if (max === b) {
    hue = (60 * ((r - g) / delta)) + 240;
  }

  let saturation = delta / max;
  let value = max / 255;

  return [hue, saturation, value];
}

