function minPath(grid, k){
    // Initialize the minimum path length to a very large number
    let minPathLength = Infinity;
    let shortestPath = [];

    // Define the directions for moving (up, down, left, right)
    const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]];

    // Function to perform DFS with memoization
    function dfs(row, col, steps, currentPath){
        if (steps === k){
            // If we have reached the required number of steps, update the shortest path
            if (currentPath.length < minPathLength || (currentPath.length === minPathLength && compareArrays(currentPath, shortestPath) < 0)){
                minPathLength = currentPath.length;
                shortestPath = [...currentPath];
            }
            return;
        }

        // Mark the current cell as visited
        grid[row][col] = -1;

        // Explore neighboring cells
        for (const [dr, dc] of directions){
            const newRow = row + dr;
            const newCol = col + dc;

            // Check if the new position is within bounds and not visited
            if (newRow >= 0 && newRow < grid.length && newCol >= 0 && newCol < grid[0].length && grid[newRow][newCol] !== -1){
                dfs(newRow, newCol, steps + 1, [...currentPath, grid[newRow][newCol]]);
            }
        }

        // Mark the current cell as unvisited
        grid[row][col] = 0;
    }

    // Start DFS from every cell
    for (let i = 0; i < grid.length; i++){
        for (let j = 0; j < grid[0].length; j++){
            dfs(i, j, 0, []);
        }
    }

    return shortestPath;
}

