function minPath(grid, k) {
    const N = grid.length;
    let directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];
    let visited = new Array(N).fill(null).map(() => new Array(N).fill(false));
    let path = [];

    function dfs(x, y, steps, path) {
        if (steps === k) {
            path.push(grid[x][y]);
            return;
        }
        for (let dir of directions) {
            const nx = x + dir[0];
            const ny = y + dir[1];
            if (nx >= 0 && nx < N && ny >= 0 && ny < N && !visited[nx][ny]) {
                visited[nx][ny] = true;
                path.push(grid[nx][ny]);
                dfs(nx, ny, steps + 1, path);
                path.pop();
                visited[nx][ny] = false;
            }
        }
    }

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            path = [];
            dfs(i, j, 0, path);
            if (path.length === k) {
                return path;
            }
        }
    }

    return []; // In case there is no path of length k
}

