function bell_number(n){
  // Base cases
  if (n === 0) return 1;
  if (n === 1) return 1;

  // Initialize a 2D array to store Bell numbers
  let bell = Array.from({ length: n + 1 }, () => Array(n + 1).fill(0));

  // Initialize the first row and column of the Bell number array
  bell[0][0] = 1;
  for (let i = 0; i <= n; i++) {
    bell[i][0] = 1;
  }

  // Calculate Bell numbers using the recurrence relation
  for (let i = 1; i <= n; i++) {
    for (let j = 1; j <= i; j++) {
      bell[i][j] = bell[i - 1][j - 1] + bell[i - 1][j];
    }
  }

  // The number of ways to partition a set of Bell numbers is the nth Bell number
  return bell[n][n];
}

function bell_number(n){
  if (n === 0) return 1;
  let bell = [1];
  for (let i = 1; i <= n; i++) {
    let nextBell = 0;
    for (let j = 0; j < i; j++) {
      nextBell += bell[j] * bell[i - j - 1];
    }
    bell.push(nextBell);
  }
  return bell[n];
}

