function find_combinations(test_list) {
    // Initialize an empty array to store the combinations
    let combinations = [];

    // Helper function to generate combinations recursively
    function generate_combinations(index, current_sum, current_combination) {
        // If the current combination sum equals the target sum, add it to the combinations array
        if (current_sum === test_list.length) {
            combinations.push(current_combination.slice());
            return;
        }

        // Iterate through the remaining elements in the test list
        for (let i = index; i < test_list.length; i++) {
            // Include the current element in the combination
            current_combination.push(test_list[i]);
            // Recursively generate combinations with the next element
            generate_combinations(i + 1, current_sum + test_list[i], current_combination);
            // Backtrack by removing the last element from the current combination
            current_combination.pop();
        }
    }

    // Start the recursive generation from the first element
    generate_combinations(0, 0, []);

    // Return the list of combinations
    return combinations;
}

