function rearrange_bigger(n) {
  // Convert the number to an array of its digits
  let digits = Array.from(String(n), Number);

  // Find the first digit from the right that can be swapped with the digit to its right
  for (let i = digits.length - 2; i >= 0; i--) {
    if (digits[i] < digits[i + 1]) {
      // Find the smallest digit to the right that is greater than digits[i]
      let j = digits.length - 1;
      while (digits[j] <= digits[i]) {
        j--;
      }
      // Swap the two digits
      [digits[i], digits[j]] = [digits[j], digits[i]];
      // Sort the digits to the right of the swapped digit in ascending order
      digits.splice(i + 1, digits.length - i - 1, ...digits.splice(i + 1, 0, ...digits.slice(i + 1).sort()));
      // Convert the array of digits back to a number
      return parseInt(digits.join(''));
    }
  }
  // If no bigger number can be formed, return 0
