function minPath(grid, k) {
  const N = grid.length;
  const directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  const visited = new Array(N).fill(0).map(() => new Array(N).fill(false));
  const path = [];
  let minPathLength = Infinity;
  let minPathValues = [];

  function dfs(row, col, steps) {
    if (steps === k) {
      if (path.length < minPathLength) {
        minPathLength = path.length;
        minPathValues = [...path];
      }
      return;
    }

    if (row < 0 || row >= N || col < 0 || col >= N || visited[row][col]) {
      return;
    }

    visited[row][col] = true;
    path.push(grid[row][col]);

    for (const [dr, dc] of directions) {
      dfs(row + dr, col + dc, steps + 1);
    }

    path.pop();
    visited[row][col] = false;
  }

  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      dfs(i, j, 0);
    }
  }

  return minPathValues;
}

function minPath(grid, k) {
    const N = grid.length;
    const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
    const visited = new Set();
    const queue = [{ row: 0, col: 0, path: [grid[0][0]] }];

    while (queue.length) {
        const { row, col, path } = queue.shift();

        if (path.length === k) {
            return path;
        }

        for (const [dr, dc] of directions) {
            const newRow = row + dr;
            const newCol = col + dc;

            if (newRow >= 0 && newRow < N && newCol >= 0 && newCol < N && !visited.has(`${newRow},${newCol}`)) {
                visited.add(`${newRow},${newCol}`);
                queue.push({ row: newRow, col: newCol, path: [...path, grid[newRow][newCol]] });
            }
        }
    }

    return null; // In case no path is found
}

