function rgb_to_hsv(r, g, b) {
    r /= 255, g /= 255, b /= 255;

    var max = Math.max(r, g, b), min = Math.min(r, g, b);
    var delta = max - min;

    var h, s;
    if (delta === 0) {
        h = s = 0;
    } else {
        if (max === r) h = (g - b) / delta % 6;
        else if (max === g) h = (b - r) / delta + 2;
        else h = (r - g) / delta + 4;

        s = delta / max;
    }

    h = Math.round(h * 360);
    s = Math.round(s * 100);
    max = Math.round(max * 100);

    return [h, s, max];
}

function rgb_to_hsv(r, g, b){
  // Normalize RGB values to the range [0, 1]
  r /= 255;
  g /= 255;
  b /= 255;

  // Calculate the maximum value
  let max = Math.max(r, g, b);

  // Calculate the minimum value
  let min = Math.min(r, g, b);

  // Calculate the saturation
  let sat = max - min;

  // Calculate the value
  let val = max;

  // Check if the color is grayscale (saturation is 0)
  if (sat === 0) {
    return [0, 0, val]; // Return [Hue, Saturation, Value]
  }

  // Calculate the hue
  let hue = (max - min) / sat;

  // Calculate the hue based on the RGB values
  if (max === r) hue = (g - b) / (max - min);
  else if (max === g) hue = (b - r) / (max - min);
  else hue = (r - g) / (max - min);

  // Convert the hue from radians to degrees
  hue = hue * 360;

  // Adjust the hue if it's greater than 360
  if (hue > 360) hue -= 360;

  // Return the HSV values
  return [hue, sat, val];
}

