function max_sum_increasing_subseq(a, n, index, k) {
  // Initialize a DP array to store the maximum sum of increasing subsequence up to each index
  const dp = new Array(n).fill(0);

  // Iterate through the array to fill the DP array
  for (let i = index; i < n; i++) {
    // Check all previous elements to find the maximum sum of increasing subsequence ending at the current index
    for (let j = 0; j < i; j++) {
      if (a[j] < a[i] && dp[j] + a[i] > dp[i]) {
        dp[i] = dp[j] + a[i];
      }
    }

    // If the kth element is after the current index, add it to the current dp value
    if (k > i) {
      dp[i] += a[k];
    }
  }

  // Return the maximum sum of increasing subsequence up to the last index
  return dp[n - 1];
}

