function minPath(grid, k){
    const N = grid.length;
    const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
    const visited = new Array(N).fill().map(() => new Array(N).fill(false));
    const path = [];
    const minPathValues = [];

    function dfs(row, col, steps) {
        if (steps === k) {
            minPathValues.push([...path]);
            return;
        }

        for (const [dr, dc] of directions) {
            const newRow = row + dr;
            const newCol = col + dc;

            if (newRow >= 0 && newRow < N && newCol >= 0 && newCol < N && !visited[newRow][newCol]) {
                visited[newRow][newCol] = true;
                path.push(grid[newRow][newCol]);
                dfs(newRow, newCol, steps + 1);
                path.pop();
                visited[newRow][newCol] = false;
            }
        }
    }

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            if (!visited[i][j]) {
                visited[i][j] = true;
                path.push(grid[i][j]);
                dfs(i, j, 1);
                path.pop();
                visited[i][j] = false;
            }
        }
    }

    minPathValues.sort((a, b) => a.toString() < b.toString());
    return minPathValues[0];
}

function minPath(grid, k){
    const N = grid.length;
    const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]]; // Right, Down, Up, Left
    let visited = new Set();
    let path = [];
    let minPath = [];

    const dfs = (i, j, steps) => {
        if (steps === k) {
            minPath = [...path];
            return;
        }
        visited.add(`${i},${j}`);
        path.push(grid[i][j]);

        for (const [dx, dy] of directions) {
            const nx = i + dx;
            const ny = j + dy;
            if (nx >= 0 && nx < N && ny >= 0 && ny < N && !visited.has(`${nx},${ny}`)) {
                dfs(nx, ny, steps + 1);
            }
        }

        path.pop();
        visited.delete(`${i},${j}`);
    };

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            dfs(i, j, 0);
        }
    }

    return minPath;
}

