function rgb_to_hsv(r, g, b) {
    r /= 255;
    g /= 255;
    b /= 255;

    let cMax = Math.max(r, g, b);
    let cMin = Math.min(r, g, b);
    let delta = cMax - cMin;

    let h;
    let s;
    let v = cMax;

    if (delta === 0) {
        h = 0;
        s = 0;
    } else {
        s = delta / v;

        let rc = (cMax - r) / delta;
        let gc = (cMax - g) / delta;
        let bc = (cMax - b) / delta;

        if (r === cMax) {
            h = (gc - bc) / delta;
        } else if (g === cMax) {
            h = 2 + (bc - rc) / delta;
        } else {
            h = 4 + (rc - gc) / delta;
        }

        h *= 60;
        if (h < 0) h += 360;
    }

    return [h, s, v];
}

function rgb_to_hsv(r, g, b) {
  // Convert RGB to HSV
  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);
  const delta = max - min;

  let h;
  let s;
  let v = max;

  if (delta === 0) {
    h = 0;
    s = 0;
  } else {
    s = delta / v;

    const rc = (max - r) / delta;
    const gc = (max - g) / delta;
    const bc = (max - b) / delta;

    if (r === max) {
      h = (gc - bc) / delta;
    } else if (g === max) {
      h = 2 + (bc - rc) / delta;
    } else if (b === max) {
      h = 4 + (rc - gc) / delta;
    }

    h *= 60;
    if (h < 0) {
      h += 360;
    }
  }

  return [h, s, v];
}

