                visited[x][y] = true;
                path.push(grid[x][y]);
                dfs(x, y, length + 1);
                path.pop();
                visited[x][y] = false;
            }
        }
    };

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            dfs(i, j, 1);
