function minPath(grid, k) {
    const N = grid.length;
    const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
    const visited = new Array(N).fill().map(() => new Array(N).fill(false));
    const path = [];
    const directionsCount = directions.length;

    const dfs = (i, j, steps) => {
        if (steps === k) {
            path.push(grid[i][j]);
            return;
        }

        for (let d = 0; d < directionsCount; d++) {
            const ni = i + directions[d][0];
            const nj = j + directions[d][1];

            if (ni >= 0 && ni < N && nj >= 0 && nj < N && !visited[ni][nj]) {
                visited[ni][nj] = true;
                dfs(ni, nj, steps + 1);
                visited[ni][nj] = false;
            }
        }
    };

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            if (!visited[i][j]) {
                visited[i][j] = true;
                dfs(i, j, 1);
                visited[i][j] = false;
                path.sort((a, b) => a - b);
            }
        }
    }

    return path.slice(0, k);
}

