function rgb_to_hsv(r, g, b) {
  // Normalize RGB values to the range [0, 1]
  r /= 255;
  g /= 255;
  b /= 255;

  // Find the maximum value and minimum value
  let max = Math.max(r, g, b);
  let min = Math.min(r, g, b);

  // Calculate the value
  let v = max;

  // Calculate the saturation
  let s = (max === 0) ? 0 : (v - min) / v;

  // Calculate the hue
  let h = 0;
  if (max === min) {
    h = 0;
  } else if (max === r) {
    h = (g - b) / (max - min);
  } else if (max === g) {
    h = 2 + (b - r) / (max - min);
  } else if (max === b) {
    h = 4 + (r - g) / (max - min);
  }

  // Convert hue from radians to degrees
  h = h * 180 / Math.PI;

  // Ensure hue is within the range [0, 360)
  h = h % 360;

  return { h: h, s: s, v: v };
}

function rgb_to_hsv(r, g, b) {
    let max = Math.max(r, g, b);
    let min = Math.min(r, g, b);
    let delta = max - min;
    let h = (max === 0) ? 0 :
        delta === 0 ? 0 :
            (max === r) ? (g - b) / delta : (max === g) ? (b - r) / delta : (r - g) / delta;
    h *= 60;
    h = h % 360;
    if (h < 0) h += 360;
    let s = delta === 0 ? 0 : delta / max;
    let v = max;
    return { h, s, v };
}

