function max_sum_increasing_subseq(a, n, index, k) {
    // Check if the index exceeds the number of elements in the array
    if (index >= n) return 0;

    // Check if the index is equal to the given k
    if (index === k) return a[k];

    // Calculate the maximum sum including the given k
    let including_k = a[k] + max_sum_increasing_subseq(a, n, index + 1, k);

    // Calculate the maximum sum without including the given k
    let excluding_k = max_sum_increasing_subseq(a, n, index + 1, k);

    // Return the maximum of the two sums
    return Math.max(including_k, excluding_k);
}

function max_sum_increasing_subseq(a, n, index, k) {
  if (index === n - 1) {
    return a[index];
  }

  let maxSum = a[index];
  for (let i = index + 1; i < n; i++) {
    if (a[i] > a[index] && i > k) {
      maxSum = Math.max(maxSum, max_sum_increasing_subseq(a, n, i, k) + a[i]);
    }
  }

  return maxSum;
}

