function get_total_number_of_sequences(m, n){
  if (m < 2 || n < 1) return 0; // Early return if m or n is invalid

  // Initialize a 2D array to store the number of sequences
  let dp = Array.from({ length: n + 1 }, () => Array(m + 1).fill(0));

  // Base case: There's one way to have a sequence of length 1 with any number
  for (let i = 1; i <= m; i++) {
    dp[1][i] = 1;
  }

  // Fill the dp array
  for (let i = 2; i <= n; i++) {
    for (let j = 2; j <= m; j++) {
      dp[i][j] = dp[i - 1][j]; // No choice if the current element is less than twice the previous one
      if (j >= 2 * (i - 1)) {
        dp[i][j] += dp[i - 1][j / 2]; // Choice if the current element is at least twice the previous one
      }
    }
  }

  // The total number of sequences is the sum of sequences of length n
  return dp[n][m];
}

function get_total_number_of_sequences(m, n) {
  // Initialize a 2D array to store the number of sequences of length i ending with number j
  const dp = Array.from({ length: n + 1 }, () => Array.from({ length: m + 1 }, () => 0));

  // Base case: There's only one way to form a sequence of length 1 ending with any number
  for (let i = 1; i <= m; i++) {
    dp[1][i] = 1;
  }

  // Fill the dp array
  for (let i = 2; i <= n; i++) {
    for (let j = 1; j <= m; j++) {
      // The number of sequences of length i ending with j is the sum of the sequences ending with all numbers less than or equal to j/2 and less than or equal to m
      for (let k = 1; k <= j / 2 && k <= m; k++) {
        dp[i][j] += dp[i - 1][k];
      }
    }
  }

  // The answer is the sum of sequences of length n ending with all numbers less than or equal to m
  return dp[n][m];
}
